  "SFMONS008MONS": { sLine: "* shrieks apprehensively *" },
  "SFMONS009MONS": { sLine: "* emits gas *" },
  "SFMONS010MONS": { sLine: "* skitters nervously *" },
  "SFMONS011MONS": { sLine: "* scans for victims *" },
  "SFMONS012MONS": { sLine: "* ponders own existence *" },
